alter table public.experience_catalog add column if not exists image_url text, add column if not exists full_description text, add column if not exists inclusions jsonb not null default '[]'::jsonb, add column if not exists duration_label text; comment on column public.experience_catalog.image_url is 'Optional public image URL for the experience card'; comment on column public.experience_catalog.inclusions is 'Guest-facing list of included activities or services';